#pragma once

namespace blitz {
	// Runs `entry` on a thread with a large stack and returns what it returned. The parser and the code generator follow the shape of the
	// program, so a long chain of terms or deeply nested blocks needs stack in proportion to its size, and the stack of the main thread
	// (8 MB on Linux, 1 MB on Windows) is used up by a few thousand of them. The stack is only reserved, it is committed when used.
	int run_with_large_stack(int (*entry)(int, char**), int argc, char** argv);
} // namespace blitz
